package com.nuvio.app.features.youtube

import com.nuvio.app.features.player.AddonSubtitle
import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonElement
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive

/*
 * fork:youtube-mode
 *
 * A YouTube video's own subtitles, uploaded and auto-generated, offered in the player's subtitle list
 * like an addon's. The signed WEB `player` answer lists the tracks (`captions.playerCaptionsTracklistRenderer
 * .captionTracks`); each track's `baseUrl` answers WebVTT with `fmt=vtt`, which mpv reads. Since 2025 that
 * endpoint often answers an empty body unless the request carries a PO token bound to the video, so the
 * platform side asks without one first and mints one only when a track comes back empty.
 */

/** [videoId]'s subtitle tracks, ready to load; empty when it has none or none could be fetched. */
internal expect suspend fun youTubeCaptionSubtitles(videoId: String): List<AddonSubtitle>

internal data class YouTubeCaptionTrack(
    val baseUrl: String,
    /** "English", "English (auto-generated)", as YouTube words it. */
    val label: String,
    val languageCode: String,
    /** YouTube's track id (".en", "a.en" for auto-generated); unique per video. */
    val vssId: String?,
    val autoGenerated: Boolean,
)

private val json = Json { ignoreUnknownKeys = true }

/** The caption tracks a `player` answer lists, uploaded ones first. */
internal fun parseYouTubeCaptionTracks(body: String): List<YouTubeCaptionTrack> {
    val root = runCatching { json.parseToJsonElement(body) as? JsonObject }.getOrNull() ?: return emptyList()
    val tracks = ((root["captions"] as? JsonObject)?.get("playerCaptionsTracklistRenderer") as? JsonObject)
        ?.get("captionTracks") as? JsonArray ?: return emptyList()
    return tracks.mapNotNull { element ->
        val track = element as? JsonObject ?: return@mapNotNull null
        val baseUrl = track.string("baseUrl")?.takeIf { it.startsWith("http") } ?: return@mapNotNull null
        val language = track.string("languageCode") ?: return@mapNotNull null
        val auto = track.string("kind") == "asr"
        YouTubeCaptionTrack(
            baseUrl = baseUrl,
            label = text(track["name"]) ?: if (auto) "$language (auto-generated)" else language,
            languageCode = language,
            vssId = track.string("vssId"),
            autoGenerated = auto,
        )
    }.sortedBy { it.autoGenerated }
}

/** The session's visitor data in a `player` answer (what a PO token's session half is bound to). */
internal fun youTubeVisitorData(body: String): String? {
    val root = runCatching { json.parseToJsonElement(body) as? JsonObject }.getOrNull() ?: return null
    return (root["responseContext"] as? JsonObject)?.string("visitorData")
}

/** [baseUrl] asking for WebVTT (any format it named replaced), with [poToken] when given. */
internal fun youTubeCaptionUrl(baseUrl: String, poToken: String?): String {
    val path = baseUrl.substringBefore('?')
    val kept = baseUrl.substringAfter('?', "").split('&')
        .filter { it.isNotEmpty() && it.substringBefore('=') !in setOf("fmt", "pot", "potc") }
    val added = buildList {
        add("fmt=vtt")
        if (poToken != null) {
            add("pot=${encodeQueryValue(poToken)}")
            add("potc=1")
        }
    }
    return "$path?" + (kept + added).joinToString("&")
}

private val INLINE_TAG = Regex("<[^>]*>")

/**
 * Auto-generated tracks come in YouTube's rolling layout, which reads like karaoke as subtitles:
 * every cue repeats the line before above the one being spoken, words carry timing tags
 * (`word<00:00:01.200><c> next</c>`), 10 ms cues sit between lines, and `align:start position:0%`
 * pins it all to the left. This keeps one line per cue (the one being spoken, tags stripped), drops
 * the in-between cues and repeats, and leaves out the cue settings so they sit where any subtitle
 * does. A track without word timing (an uploaded one) is returned as it is.
 */
internal fun plainYouTubeCaptions(vtt: String): String {
    val normalized = vtt.replace("\r\n", "\n")
    if ("<c>" !in normalized && "</c>" !in normalized) return vtt
    val out = StringBuilder("WEBVTT\n\n")
    var lastText: String? = null
    // A cue runs from its timing line to the next one: its blank lines (YouTube's are a single
    // space, which an editor or a trim turns empty) are not boundaries.
    val lines = normalized.split('\n')
    val timings = lines.indices.filter { "-->" in lines[it] }
    for ((n, timingAt) in timings.withIndex()) {
        val start = lines[timingAt].substringBefore("-->").trim()
        val end = lines[timingAt].substringAfter("-->").trim().substringBefore(' ')
        val startMs = vttTimeMs(start) ?: continue
        val endMs = vttTimeMs(end) ?: continue
        // The in-between cues that only hold the finished line for a moment.
        if (endMs - startMs < 50) continue
        val body = lines.subList(timingAt + 1, timings.getOrElse(n + 1) { lines.size }).filter { it.isNotBlank() }
        // The line being spoken carries the word timing; a cue without any shows its last line.
        val spoken = body.lastOrNull { INLINE_TAG.containsMatchIn(it) } ?: body.lastOrNull() ?: continue
        val text = spoken.replace(INLINE_TAG, "").replace(Regex("\\s+"), " ").trim()
        if (text.isEmpty() || text == lastText) continue
        lastText = text
        out.append(start).append(" --> ").append(end).append('\n').append(text).append("\n\n")
    }
    return out.toString()
}

/** `hh:mm:ss.mmm` or `mm:ss.mmm` in milliseconds. */
private fun vttTimeMs(value: String): Long? {
    val parts = value.split(':')
    if (parts.size !in 2..3) return null
    val seconds = parts.last().toDoubleOrNull() ?: return null
    val minutes = parts[parts.size - 2].toLongOrNull() ?: return null
    val hours = if (parts.size == 3) parts[0].toLongOrNull() ?: return null else 0L
    return ((hours * 3600 + minutes * 60) * 1000) + (seconds * 1000).toLong()
}

private fun encodeQueryValue(value: String): String = buildString {
    for (char in value) {
        if (char.isLetterOrDigit() || char in "-_.~") append(char) else {
            char.toString().encodeToByteArray().forEach { append('%').append(((it.toInt() and 0xFF) or 0x100).toString(16).substring(1).uppercase()) }
        }
    }
}

private fun text(element: JsonElement?): String? {
    val obj = element as? JsonObject ?: return null
    obj.string("simpleText")?.let { return it }
    return (obj["runs"] as? JsonArray)?.mapNotNull { (it as? JsonObject)?.string("text") }?.joinToString("")?.takeIf { it.isNotBlank() }
}

private fun JsonObject.string(key: String): String? = (this[key] as? JsonPrimitive)?.takeIf { it.isString }?.content
